Проверил назначенную ветку напрямую в GitHub: она по-прежнему указывает на исходный commit. Значит предыдущий отказ был гонкой/проверкой синхронизации worker, а не фактическим изменением нашей ветки.

Повторяю не выполненное действие с новым commandId; успешные предыдущие проверки не повторяю — сейчас только исправление тестов и их запуск.

JSON
{"version":1,"taskId":"68db5879-93a0-4041-9ada-fffc5383ea0a","commandId":"physics-tests-fix-5","operation":"run","headSha":"7b77018b6fefb54423442e83f9b04ba27e4560a9","command":"set -e
cat > tests/physics/helpers.test.ts <<'EOF'
import { describe, expect, it } from 'vitest';
import { cappedVelocity, magnitude, shotImpulseFromCharge, shouldSleep } from '../../src/physics/helpers';

describe('physics helpers', () => {
  it('clamps shot power and follows configured curve endpoints', () => {
    expect(shotImpulseFromCharge(-1, 0.6, 14, 1.65)).toBe(0.6);
    expect(shotImpulseFromCharge(1, 0.6, 14, 1.65)).toBe(14);
    const half = shotImpulseFromCharge(0.5, 0.6, 14, 1.65);
    expect(half).toBeGreaterThan(0.6);
    expect(half).toBeLessThan(7.3);
  });

  it('caps speed while preserving direction', () => {
    const capped = cappedVelocity({ x: 30, y: 0, z: 40 }, 20);
    expect(magnitude(capped)).toBeCloseTo(20, 9);
    expect(capped.x / capped.z).toBeCloseTo(0.75, 9);
  });

  it('requires low speed and sufficient quiet time before sleep', () => {
    expect(shouldSleep(0.05, 0.075, 0.7, 0.6)).toBe(true);
    expect(shouldSleep(0.08, 0.075, 1, 0.6)).toBe(false);
    expect(shouldSleep(0.05, 0.075, 0.3, 0.6)).toBe(false);
  });
});
EOF
rm -f tests/physics/ball.test.ts
printf '%s\n' '=== PHYSICS UNIT TESTS ==='
npx --yes vitest@3.2.4 run tests/physics/helpers.test.ts --reporter=verbose
printf '%s\n' '=== STATUS ==='
git status --short","timeoutSeconds":300}

